#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <set>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int L, C;
    if (!(cin >> L >> C)) return 0;

    vector<vector<string>> grid(L, vector<string>(C));
    vector<long long> row_sum(L);
    vector<long long> col_sum(C);

    set<string> distinct_vars;

    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < C; ++j) {
            cin >> grid[i][j];
            distinct_vars.insert(grid[i][j]);
        }
        cin >> row_sum[i];
    }

    for (int j = 0; j < C; ++j) {
        cin >> col_sum[j];
    }

    map<string, long long> val;
    set<string> known;

    int total_vars = distinct_vars.size();

    while ((int)known.size() < total_vars) {
        bool progress = false;

        // Check rows
        for (int i = 0; i < L; ++i) {
            set<string> unknown_in_row;
            long long known_sum = 0;
            int unknown_count = 0;
            string unknown_var = "";

            for (int j = 0; j < C; ++j) {
                string v = grid[i][j];
                if (known.count(v)) {
                    known_sum += val[v];
                } else {
                    unknown_in_row.insert(v);
                    unknown_var = v;
                    unknown_count++;
                }
            }

            if (unknown_in_row.size() == 1) {
                val[unknown_var] = (row_sum[i] - known_sum) / unknown_count;
                known.insert(unknown_var);
                progress = true;
                break;
            }
        }

        if (progress) continue;

        // Check cols
        for (int j = 0; j < C; ++j) {
            set<string> unknown_in_col;
            long long known_sum = 0;
            int unknown_count = 0;
            string unknown_var = "";

            for (int i = 0; i < L; ++i) {
                string v = grid[i][j];
                if (known.count(v)) {
                    known_sum += val[v];
                } else {
                    unknown_in_col.insert(v);
                    unknown_var = v;
                    unknown_count++;
                }
            }

            if (unknown_in_col.size() == 1) {
                val[unknown_var] = (col_sum[j] - known_sum) / unknown_count;
                known.insert(unknown_var);
                progress = true;
                break;
            }
        }
    }

    for (const auto& kv : val) {
        cout << kv.first << " " << kv.second << "\n";
    }

    return 0;
}
